const data = $json.body || $json;
const content = (data.content || '').toLowerCase().trim();
const messageType = data.message_type;
const event = data.event;
const contentAttrs = data.content_attributes || {};
const conversation = data.conversation || {};
const customAttrs = conversation.custom_attributes || {};

console.log('Incoming:', content, 'Type:', messageType, 'Event:', event, 'State:', customAttrs.bot_state);

// Skip outgoing and updated messages
if (event === 'message_updated' || messageType === 'outgoing') {
  return { json: { route: 'SKIP', skip: true, conversationId: conversation.id } };
}

let route = 'UNKNOWN';
let nextState = customAttrs.bot_state || null;

// State-based routing
if (customAttrs.bot_state === 'region_asked' && messageType === 'incoming') {
  route = 'REGION_RESPONSE';
} else if (customAttrs.bot_state === 'guitar_list_shown' && messageType === 'incoming') {
  route = 'GUITAR_RESPONSE';
} else if (customAttrs.bot_state === 'payment_request' && messageType === 'incoming') {
  route = 'PAYMENT_RESPONSE';
} else if (customAttrs.bot_state === 'appointment_booking' && messageType === 'incoming') {
  route = 'TIME_RESPONSE';
} else if (customAttrs.bot_state === 'name_selection_asked' && messageType === 'incoming') {
  route = 'NAME_SELECTION_RESPONSE';
} else if (customAttrs.bot_state === 'form_shown' && messageType === 'incoming') {
  route = 'FORM_RESPONSE';
  nextState = 'form_submitted';
}
// List picker selections
else if (contentAttrs.interactive_type === 'list_picker') {
  const items = contentAttrs.interactive_data?.data?.['list-picker']?.selectedItems || [];
  if (items.length > 0) {
    const id = items[0].identifier;
    if (id === 'menu_intent') { route = 'INTENT_SETUP'; nextState = 'intent_asked'; }
    else if (id === 'menu_listpicker') { route = 'GUITAR'; nextState = 'guitar_list_shown'; }
    else if (id === 'menu_ar') { route = 'AR_DIRECT'; nextState = 'ar_sent'; }
    else if (id === 'menu_applepay') { route = 'PAYMENT'; nextState = 'payment_request'; }
    else if (id === 'menu_timepicker') { route = 'TIME'; nextState = 'time_picker_shown'; }
    else if (id === 'menu_form') { route = 'FORM'; nextState = 'form_shown'; }
    else if (id === 'menu_image') { route = 'IMAGE_REQUEST'; nextState = 'image_requested'; }
    else if (id === 'menu_documents') { route = 'DOCUMENTS'; nextState = 'documents_sent'; }
    else if (id === 'menu_authenticate') { route = 'AUTH'; nextState = 'auth_requested'; }
    else if (id === 'menu_imessageapp') { route = 'IMESSAGE_APP'; nextState = 'imessage_shown'; }
    else if (id === 'menu_wallet') { route = 'WALLET'; nextState = 'wallet_shown'; }
    else if (id === 'menu_location') { route = 'LOCATION'; nextState = 'location_request'; }
    else if (id.includes('guitar_')) { route = 'GUITAR_SELECTED'; nextState = 'guitar_selected'; }
    else if (id.includes('ar_')) { route = 'AR'; nextState = 'ar_prompt'; }
  }
}
// Interactive type routing
else if (contentAttrs.interactive_type === 'time_picker') {
  route = 'CONFIRM'; nextState = 'appointment_confirmed';
} else if (contentAttrs.interactive_type === 'form' || contentAttrs.interactive_type === 'apple_form_response') {
  route = 'FORM_RESPONSE'; nextState = 'form_submitted';
} else if (contentAttrs.interactive_type === 'quick_reply') {
  const reply = contentAttrs.interactive_data?.data?.['quick-reply']?.identifier || '';
  if (reply.includes('region_')) { route = 'REGION_RESPONSE'; nextState = 'region_selected'; }
  else if (reply === 'name_real' || reply === 'name_stage') { route = 'NAME_SELECTED'; nextState = 'name_selected'; }
  else if (reply === 'ar_view_yes' || reply === '111') {
    route = customAttrs.bot_state === 'ar_view_asked' ? 'AR_VIEW_YES' : 'AR_PLACE_YES';
    nextState = route.toLowerCase();
  } else if (reply === 'ar_view_no' || reply === '222') {
    route = customAttrs.bot_state === 'ar_view_asked' ? 'AR_VIEW_NO' : 'AR_PLACE_NO';
    nextState = route.toLowerCase();
  }
}
// Text keyword routing
else if (['start', 'hello', 'hi', 'help', 'begin'].includes(content)) { route = 'WELCOME'; nextState = 'welcomed'; }
else if (['menu', 'main menu'].includes(content)) { route = 'MENU'; nextState = 'menu_shown'; }
else if (['startover', 'start over', 'restart'].includes(content)) { route = 'RESTART'; nextState = null; }
else if (['summary', 'features'].includes(content)) { route = 'FEATURES'; nextState = 'features_shown'; }
else if (content === 'stop') { route = 'STOP'; nextState = 'stopped'; }
else if (['list picker', 'listpicker', 'guitar', 'guitars'].includes(content)) { route = 'GUITAR'; nextState = 'guitar_list_shown'; }
else if (['time picker', 'timepicker', 'appointment', 'time'].includes(content)) { route = 'TIME'; nextState = 'time_picker_shown'; }
else if (['apple pay', 'payment', 'pay'].includes(content)) { route = 'PAYMENT'; nextState = 'payment_request'; }
else if (['form', 'help me decide'].includes(content)) { route = 'FORM'; nextState = 'form_shown'; }
else if (['rich link', 'richlink'].includes(content)) { route = 'RICH_LINK'; nextState = 'rich_link_shown'; }
else if (['quick reply', 'qr'].includes(content)) { route = 'QUICK_REPLY'; nextState = 'qr_shown'; }
else if (['location', 'locator', 'store', 'stores'].includes(content)) { route = 'LOCATION'; nextState = 'location_request'; }
else if (['ar', 'augmented reality'].includes(content)) { route = 'AR_DIRECT'; nextState = 'ar_sent'; }
else if (content === 'wallet') { route = 'WALLET'; nextState = 'wallet_shown'; }
else if (['authenticate', 'authentication'].includes(content)) { route = 'AUTH'; nextState = 'auth_requested'; }
else if (['imessageapp', 'imessage app', 'imessageextension'].includes(content)) { route = 'IMESSAGE_APP'; nextState = 'imessage_shown'; }
else if (content === 'airport') { route = 'AIRPORT'; nextState = 'airport_shown'; }
else if (['survey', 'csat'].includes(content)) { route = 'SURVEY'; nextState = 'survey_shown'; }
else if (['documents', 'docs'].includes(content)) { route = 'DOCUMENTS'; nextState = 'documents_sent'; }
else if (['image', 'photo', 'selfie'].includes(content)) { route = 'IMAGE_REQUEST'; nextState = 'image_requested'; }

console.log('ROUTE:', route, 'NEXT_STATE:', nextState);

return {
  json: {
    route: route,
    nextState: nextState,
    conversationId: conversation.id,
    accountId: data.account?.id || 1,
    rawContent: content,
    rawData: data
  }
};

// Parse Guitar List selection from interactive response
const webhookData = $('Webhook').item.json.body || $('Webhook').item.json;
const contentAttrs = webhookData.content_attributes || {};
const interactive = contentAttrs.interactive_data?.data?.['list-picker'] || {};
const selected = interactive.selectedItems?.[0] || {};

const guitarIdentifier = selected.identifier || '';
const guitarTitle = selected.title || '';

console.log('=== Parse Guitar Selection ===');
console.log('Guitar selected:', guitarIdentifier, guitarTitle);
console.log('Account ID:', webhookData.account ? webhookData.account.id : 1);
console.log('Conversation ID:', webhookData.conversation ? webhookData.conversation.id : null);

return {
  json: {
    guitarIdentifier: guitarIdentifier,
    guitarTitle: guitarTitle,
    conversationId: webhookData.conversation?.id,
    accountId: webhookData.account ? webhookData.account.id : 1
  }
};

// AHB1 - Parse Help Me Decide Form Response
const data = $json.body || $json;
const contentAttrs = data.content_attributes || {};
const formData = contentAttrs.interactive_data?.data?.form || {};
const items = formData.items || [];

// Extract name from field 4 (index 3)
let userName = '';
let stageName = '';

if (items.length > 3 && items[3].items && items[3].items.length > 0) {
  userName = items[3].items[0].value || '';
}

// Extract optional stage name from field 5 (index 4)
if (items.length > 4 && items[4].items && items[4].items.length > 0) {
  stageName = items[4].items[0].value || '';
}

console.log('AHB1 - Name:', userName, 'Stage Name:', stageName);

return {
  json: {
    ...($json || {}),
    userName: userName,
    stageName: stageName,
    hasStageName: stageName !== '',
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// AHB2 - Select Name based on Quick Reply
const webhookData = $('Webhook').item.json.body || $('Webhook').item.json;
const contentAttrs = webhookData.content_attributes || {};
const quickReply = contentAttrs.interactive_data?.data?.['quick-reply'] || {};
const identifier = quickReply.identifier || '';

// Get the previously stored names from custom attributes
const conversation = webhookData.conversation || {};
const customAttrs = conversation.custom_attributes || {};

let selectedName = '';
if (identifier === 'name_real') {
  selectedName = customAttrs.user_name || '';
} else if (identifier === 'name_stage') {
  selectedName = customAttrs.stage_name || '';
}

console.log('=== AHB2 - Select Name ===');
console.log('Identifier:', identifier);
console.log('Selected Name:', selectedName);
console.log('Account ID:', webhookData.account ? webhookData.account.id : 1);
console.log('Conversation ID:', conversation.id);

return {
  json: {
    selectedName: selectedName,
    nameSelection: identifier,
    conversationId: conversation.id,
    accountId: webhookData.account ? webhookData.account.id : 1
  }
};

// AHB1_2 - Parse text name input (fallback when form capability not available)
const data = $json.body || $json;
const content = data.content || '';

// Capitalize first letter
const name = content.charAt(0).toUpperCase() + content.slice(1);

console.log('AHB1_2 - Text name:', name);

return {
  json: {
    ...($json || {}),
    selectedName: name,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// Parse location text input (zipcode or city)
const data = $json.body || $json;
const content = data.content || '';
const location = content.trim();

console.log('AHG1 - Location input:', location);

// Simple validation: check if it looks like a zipcode or city name
let isValid = location.length > 0;

return {
  json: {
    ...($json || {}),
    location: location,
    isValid: isValid,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// Parse Continue Quick Reply Response
const data = $json.body || $json;
const contentAttrs = data.content_attributes || {};
const quickReply = contentAttrs.interactive_data?.data?.['quick-reply'] || {};
const identifier = quickReply.identifier || '';

console.log('AHI1 - Continue identifier:', identifier);

let shouldContinue = identifier === 'continue_yes';

return {
  json: {
    ...($json || {}),
    shouldContinue: shouldContinue,
    continueIdentifier: identifier,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// AHC1 - Guitar Picker Catcher
const data = $json.body || $json;
const conversation = data.conversation || {};
const customAttrs = conversation.custom_attributes || {};
const botState = customAttrs.bot_state || '';
const retryCount = customAttrs.retry_count || 0;

// Check if we're in guitar_list state and user hasn't responded
const isGuitarState = botState === 'guitar_list';
const conversationId = conversation.id;
const accountId = data.account?.id || 1;

return {
  json: {
    isGuitarState: isGuitarState,
    retryCount: retryCount,
    conversationId: conversationId,
    accountId: accountId,
    shouldPrompt: retryCount === 2,
    shouldResend: retryCount === 3,
    shouldAutoSelect: retryCount >= 5
  }
};

// AHF1 - Apple Pay Catcher
const data = $json.body || $json;
const conversation = data.conversation || {};
const customAttrs = conversation.custom_attributes || {};
const botState = customAttrs.bot_state || '';
const retryCount = customAttrs.retry_count || 0;
const userName = customAttrs.selected_name || customAttrs.user_name || 'there';

// Check if we're in payment_request state
const isPaymentState = botState === 'payment_request';
const conversationId = conversation.id;
const accountId = data.account?.id || 1;

return {
  json: {
    isPaymentState: isPaymentState,
    retryCount: retryCount,
    conversationId: conversationId,
    accountId: accountId,
    userName: userName,
    shouldSkipPayment: retryCount > 2
  }
};

// AHH1 - Time Picker Catcher
const data = $json.body || $json;
const conversation = data.conversation || {};
const customAttrs = conversation.custom_attributes || {};
const botState = customAttrs.bot_state || '';
const retryCount = customAttrs.retry_count || 0;

// Check if we're in appointment_booking state
const isTimePickerState = botState === 'appointment_booking';
const conversationId = conversation.id;
const accountId = data.account?.id || 1;

return {
  json: {
    isTimePickerState: isTimePickerState,
    retryCount: retryCount,
    conversationId: conversationId,
    accountId: accountId,
    shouldPrompt: retryCount === 2,
    shouldResend: retryCount === 3,
    shouldSkip: retryCount >= 5
  }
};

