// Parse Store Selection
const data = $json.body || $json;
const contentAttrs = data.content_attributes || {};
const interactive = contentAttrs.interactive_data?.data?.['list-picker'] || {};
const selected = interactive.selectedItems?.[0] || {};

const storeIdentifier = selected.identifier || '';
const storeTitle = selected.title || '';

console.log('Store selected:', storeIdentifier, storeTitle);

return {
  json: {
    storeIdentifier: storeIdentifier,
    storeTitle: storeTitle,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// Parse Auth Selection
const data = $json.body || $json;
const contentAttrs = data.content_attributes || {};
const interactive = contentAttrs.interactive_data?.data?.['list-picker'] || {};
const selected = interactive.selectedItems?.[0] || {};

const authType = selected.identifier || '';

let message = '';
if (authType === 'auth_linkedin') {
  message = '✅ LinkedIn OAuth Selected\n\nTODO: Setup OAuth app at https://www.linkedin.com/developers/\n- Implement OAuth callback handler\n- Exchange for user profile data\n- Store access tokens securely';
} else if (authType === 'auth_native') {
  message = '✅ Native Auth Selected\n\nTODO: Configure Apple Messages for Business native auth\n- Requires native auth capability\n- Handle auth tokens in backend\n- iOS native authentication flow';
} else if (authType === 'auth_server_side') {
  message = '✅ Server-Side Auth Selected\n\nTODO: Setup auth server endpoint\n- Implement token exchange\n- Store user session data\n- Provide auth status API';
}

return {
  json: {
    authType: authType,
    message: message,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// Parse region selection from Quick Reply response
const webhookData = $('Webhook').item.json.body || $('Webhook').item.json;

console.log('=== Parse Region Selection ===');

// Extract from webhook data
const content = (webhookData.content || '').toLowerCase().trim();
const contentAttrs = webhookData.content_attributes || {};
const conversation = webhookData.conversation || {};
const interactiveData = contentAttrs.interactive_data || {};
const quickReplyData = interactiveData.data ? interactiveData.data['quick-reply'] : null;

console.log('Webhook content:', content);

// Extract region from Quick Reply
let region = 'unknown';

// Method 1: Check items array
if (quickReplyData && quickReplyData.items && quickReplyData.items.length > 0) {
  const selectedItem = quickReplyData.items[0];
  const itemContent = (selectedItem.content || '').toLowerCase();

  console.log('Method 1 - Checking items array');
  console.log('Item content:', itemContent);

  if (itemContent === 'emea') {
    region = 'EMEA';
    console.log('SUCCESS: Found EMEA');
  } else if (itemContent === 'americas') {
    region = 'Americas';
    console.log('SUCCESS: Found Americas');
  } else if (itemContent === 'apac') {
    region = 'APAC';
    console.log('SUCCESS: Found APAC');
  }
}

// Method 2: Check identifier field
if (region === 'unknown' && quickReplyData && quickReplyData.identifier) {
  const identifier = quickReplyData.identifier.toLowerCase();

  console.log('Method 2 - Checking identifier');
  console.log('Identifier:', identifier);

  if (identifier.includes('emea')) {
    region = 'EMEA';
    console.log('SUCCESS: Found EMEA');
  } else if (identifier.includes('americas')) {
    region = 'Americas';
    console.log('SUCCESS: Found Americas');
  } else if (identifier.includes('apac')) {
    region = 'APAC';
    console.log('SUCCESS: Found APAC');
  }
}

// Method 3: Check value field
if (region === 'unknown' && quickReplyData && quickReplyData.value) {
  const value = quickReplyData.value.toLowerCase();

  console.log('Method 3 - Checking value');
  console.log('Value:', value);

  if (value === 'emea') {
    region = 'EMEA';
    console.log('SUCCESS: Found EMEA');
  } else if (value === 'americas') {
    region = 'Americas';
    console.log('SUCCESS: Found Americas');
  } else if (value === 'apac') {
    region = 'APAC';
    console.log('SUCCESS: Found APAC');
  }
}

// Method 4: Fallback to content text
if (region === 'unknown') {
  console.log('Method 4 - Checking content text');
  console.log('Content:', content);

  if (content.includes('emea') || content === 'emea') {
    region = 'EMEA';
    console.log('SUCCESS: Found EMEA');
  } else if (content.includes('americas') || content === 'americas') {
    region = 'Americas';
    console.log('SUCCESS: Found Americas');
  } else if (content.includes('apac') || content === 'apac') {
    region = 'APAC';
    console.log('SUCCESS: Found APAC');
  }
}

console.log('');
console.log('FINAL RESULT - Region:', region);
console.log('Account ID:', webhookData.account ? webhookData.account.id : 1);
console.log('Conversation ID:', conversation.id);
console.log('==============================');

return {
  json: {
    accountId: webhookData.account ? webhookData.account.id : 1,
    conversationId: conversation.id,
    region: region,
    userId: webhookData.sender ? webhookData.sender.id : null
  }
};

// Parse Apple Pay Response
const data = $json.body || $json;
const contentAttrs = data.content_attributes || {};
const applePayData = contentAttrs.interactive_data?.data?.['apple-pay'] || {};

console.log('=== Parse Payment Response ===');
console.log('Apple Pay Data:', applePayData);

// Extract payment status
const paymentStatus = applePayData.status || 'unknown';
const transactionId = applePayData.transactionIdentifier || '';

// Extract billing/shipping info if present
const billingContact = applePayData.billingContact || {};
const shippingContact = applePayData.shippingContact || {};

console.log('Payment Status:', paymentStatus);
console.log('Transaction ID:', transactionId);

return {
  json: {
    ...($json || {}),
    paymentStatus: paymentStatus,
    transactionId: transactionId,
    billingContact: billingContact,
    shippingContact: shippingContact,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};

// Parse Time Picker Response
const data = $json.body || $json;
const contentAttrs = data.content_attributes || {};
const timePickerData = contentAttrs.interactive_data?.data?.['time-picker'] || {};

console.log('=== Parse Time Response ===');
console.log('Time Picker Data:', timePickerData);

// Extract selected time slot
const selectedSlot = timePickerData.selectedItem || {};
const eventIdentifier = selectedSlot.identifier || '';
const eventTitle = selectedSlot.title || '';

// Parse the time from identifier or title
let selectedTime = '';
let selectedDate = '';

if (eventIdentifier) {
  // Format: "slot_YYYYMMDD_HHMM"
  const parts = eventIdentifier.split('_');
  if (parts.length >= 3) {
    selectedDate = parts[1];  // YYYYMMDD
    selectedTime = parts[2];  // HHMM
  }
}

console.log('Selected Date:', selectedDate);
console.log('Selected Time:', selectedTime);
console.log('Event Title:', eventTitle);

return {
  json: {
    ...($json || {}),
    selectedDate: selectedDate,
    selectedTime: selectedTime,
    eventTitle: eventTitle,
    eventIdentifier: eventIdentifier,
    conversationId: data.conversation?.id,
    accountId: data.account?.id || 1
  }
};
